BEGIN;
TRUNCATE outfit_items, outfits, items, activity_log, users CASCADE;
SELECT setval(pg_get_serial_sequence('items','id'), coalesce((SELECT max(id) FROM items),1));
SELECT setval(pg_get_serial_sequence('outfits','id'), coalesce((SELECT max(id) FROM outfits),1));
SELECT setval(pg_get_serial_sequence('outfit_items','id'), coalesce((SELECT max(id) FROM outfit_items),1));
SELECT setval(pg_get_serial_sequence('activity_log','id'), coalesce((SELECT max(id) FROM activity_log),1));
COMMIT;
